<?php
namespace App\Http\Controllers;
use App\Models\PublicHoliday; use App\Services\WorkforceAuditService; use App\Services\WorkforceFeatureService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class WorkforceSettingsController extends Controller { public function index(WorkforceFeatureService $svc){$features=[];foreach(WorkforceFeatureService::FEATURES as $key=>$label)$features[$key]=['label'=>$label,'enabled'=>$svc->enabled($key),'dependencies'=>$svc->dependencies($key)];$rates=DB::table('statutory_rate_profiles')->orderByDesc('effective_from')->get(); $holidays=PublicHoliday::query()->whereDate('holiday_date','>=',now()->startOfYear())->orderBy('holiday_date')->get(); return view('workforce.settings.index',compact('features','rates','holidays'));}
public function storeHoliday(Request $r, WorkforceAuditService $audit){$d=$r->validate(['holiday_date'=>'required|date','name'=>'required|string|max:150','holiday_type'=>'required|in:public,mercantile,organisation']);$d['is_active']=true;$d['created_by']=auth()->id();$holiday=PublicHoliday::updateOrCreate(['holiday_date'=>$d['holiday_date']],$d);$audit->model('updated',$holiday,'Public holiday calendar updated');return back()->with('success','Holiday calendar updated.');}
public function toggle(Request $r, WorkforceFeatureService $svc, WorkforceAuditService $audit){$d=$r->validate(['feature'=>'required|string','enabled'=>'required|boolean','payroll_override_reason'=>'nullable|string|max:500','governance_override_reason'=>'nullable|string|max:500']);abort_unless(array_key_exists($d['feature'],WorkforceFeatureService::FEATURES),422); if($d['feature']==='payroll' && $d['enabled'] && \App\Models\SystemSetting::getBool('payroll_external_system_authoritative',true) && mb_strlen(trim((string)($d['payroll_override_reason']??'')))<8) return back()->withErrors(['payroll_override_reason'=>'A governance reason is required before enabling internal Payroll while the external Government-approved payroll system is authoritative.']);$privateDefault=['biometric_attendance','leave_automation','contract_lifecycle','locum_pool','demand_forecasting','roster_optimizer']; if($d['enabled'] && \App\Services\SectorProfileService::isGovernment() && in_array($d['feature'],$privateDefault,true) && mb_strlen(trim((string)($d['governance_override_reason']??'')))<8) return back()->withErrors(['governance_override_reason'=>'A governance reason is required before enabling this private-sector support feature in a Government deployment.']);if($d['enabled'])foreach($svc->dependencies($d['feature']) as $dep)if(!$svc->enabled($dep))return back()->withErrors(['feature'=>"Enable {$dep} before enabling {$d['feature']}."]); if(!$d['enabled']){foreach(WorkforceFeatureService::FEATURES as $candidate=>$label){if($svc->enabled($candidate) && in_array($d['feature'],$svc->dependencies($candidate),true)) return back()->withErrors(['feature'=>"Disable {$candidate} before disabling {$d['feature']}."]);}}$key=$svc->settingKey($d['feature']); abort_unless($key,422); DB::table('system_settings')->updateOrInsert(['key'=>$key],['value'=>$d['enabled']?'1':'0','type'=>'boolean','group'=>'features','updated_at'=>now(),'created_at'=>now()]);$audit->log('updated','SystemSetting',null,"Feature {$d['feature']} ".($d['enabled']?'enabled':'disabled').(!empty($d['payroll_override_reason'])?': '.trim($d['payroll_override_reason']):'').(!empty($d['governance_override_reason'])?': '.trim($d['governance_override_reason']):''),[],['key'=>$key,'value'=>$d['enabled']]);return back()->with('success','Module setting updated.');}}